window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-10201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτυεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1683 na letra δ · nº geral 10201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pesca com rede. 〈δικτυεύς〉</p></section></article>\n<article id=\"entry-dgp-10202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτυεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1684 na letra δ · nº geral 10202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pescador. 〈δίκτυον〉</p></section></article>\n<article id=\"entry-dgp-10203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ίκτυννα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1685 na letra δ · nº geral 10203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Dictina, a Caçadora, epít. de Ártemis. 〈δίκτυον〉</p></section></article>\n<article id=\"entry-dgp-10204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτυόκλωστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1686 na letra δ · nº geral 10204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">entrelaçado como rede ou que é entrelaçado. 〈δίκτυον, κλώθω〉</p></section></article>\n<article id=\"entry-dgp-10205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκτυον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1687 na letra δ · nº geral 10205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rede de pesca ou de caça 2 cilada.</p></section></article>\n<article id=\"entry-dgp-10206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτυουλκός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1688 na letra δ · nº geral 10206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que atira a rede; pescador. 〈δίκτυον, ἕλκω〉</p></section></article>\n<article id=\"entry-dgp-10207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικτυόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1689 na letra δ · nº geral 10207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prender na rede. 〈δίκτυον〉</p></section></article>\n<article id=\"entry-dgp-10208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκτυς, υος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1690 na letra δ · nº geral 10208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dictis, animal africano não identificado.</p></section></article>\n<article id=\"entry-dgp-10209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1691 na letra δ · nº geral 10209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. δίκων) lançar; atirar.</p></section></article>\n<article id=\"entry-dgp-10210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δικωπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1692 na letra δ · nº geral 10210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">embarcação com dois remos. 〈δίκωπος〉</p></section></article>\n<article id=\"entry-dgp-10211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίκωπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1693 na letra δ · nº geral 10211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com dois remos. 〈δίς, κώπη〉</p></section></article>\n<article id=\"entry-dgp-10212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίλογος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1694 na letra δ · nº geral 10212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. de duas palavras; dissimulado; matreiro. 〈δίς, λόγος〉</p></section></article>\n<article id=\"entry-dgp-10213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίλογχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1695 na letra δ · nº geral 10213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de dupla ponta 2 duplo. 〈δίς, λόγχη〉</p></section></article>\n<article id=\"entry-dgp-10214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίλοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1696 na letra δ · nº geral 10214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem dois cumes. 〈δίς, λόφος〉</p></section></article>\n<article id=\"entry-dgp-10215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίμηνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1697 na letra δ · nº geral 10215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura dois meses ♦ ἡ δίμηνος e τὸ δίμηνον 2 duração de dois meses. 〈δίς, μήν〉</p></section></article>\n<article id=\"entry-dgp-10216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίμιτρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1698 na letra δ · nº geral 10216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem mitra dupla. 〈δίς, μίτρα〉</p></section></article>\n<article id=\"entry-dgp-10217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διμναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1699 na letra δ · nº geral 10217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vale duas minas. 〈δίς, μνᾶ〉</p></section></article>\n<article id=\"entry-dgp-10218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίμνεως, εως, εων</h1><div class=\"entry-meta\"><span>DGP · ordem 1700 na letra δ · nº geral 10218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διμναῖος.</p></section></article>\n<article id=\"entry-dgp-10219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διμοιρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1701 na letra δ · nº geral 10219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 porção dupla; parte dupla 2 duplo soldo 3 dois terços. 〈δίς, μοῖρα〉</p></section></article>\n<article id=\"entry-dgp-10220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διμοιρίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1702 na letra δ · nº geral 10220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que recebe soldo duplo ou dupla ração 2 aquele que comanda uma meia-coorte. 〈διμοιρία〉</p></section></article>\n<article id=\"entry-dgp-10221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίμοιρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1703 na letra δ · nº geral 10221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 repartido em dois: δ. μέρος dois terços ♦ τὸ δίμοιρον 2 dois terços. 〈δίς, μοῖρα〉</p></section></article>\n<article id=\"entry-dgp-10222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ινδυμήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1704 na letra δ · nº geral 10222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deusa do monte Díndimo, i.e., Cibele.</p></section></article>\n<article id=\"entry-dgp-10223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ίνδυμον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1705 na letra δ · nº geral 10223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Díndimo, monte da Frígia.</p></section></article>\n<article id=\"entry-dgp-10224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινεύεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 1706 na letra δ · nº geral 10224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de δινεύω.</p></section></article>\n<article id=\"entry-dgp-10225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1707 na letra δ · nº geral 10225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">δινέω.</p></section></article>\n<article id=\"entry-dgp-10226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1708 na letra δ · nº geral 10226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer dar voltas; fazer girar; girar 2 agitar; sacudir; brandir, dando voltas 3 lançar, fazendo voltear 4 dar voltas em todos os sentidos 5 ir e vir; andar errante ♦ méd. 6 dar voltas; errar 7 mover-se; agitar-se.</p></section></article>\n<article id=\"entry-dgp-10227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1709 na letra δ · nº geral 10227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 turbilhão 2 movimento de rotação.</p></section></article>\n<article id=\"entry-dgp-10228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1710 na letra δ · nº geral 10228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dá muitas voltas; que gira; que faz redemoinho 2 arredondado. 〈δίνη〉</p></section></article>\n<article id=\"entry-dgp-10229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δῖνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1711 na letra δ · nº geral 10229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 torvelinho; redemoinho 2 rotação 3 ator­doamento; vertigem 4 eira 5 vasilha torneada. 〈δίνη〉</p></section></article>\n<article id=\"entry-dgp-10230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1712 na letra δ · nº geral 10230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cheio de redemoinhos. 〈δῖνος〉</p></section></article>\n<article id=\"entry-dgp-10231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δινωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1713 na letra δ · nº geral 10231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito em torno; arredondado. 〈δῖνος〉</p></section></article>\n<article id=\"entry-dgp-10232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διξός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1714 na letra δ · nº geral 10232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = δισσός.</p></section></article>\n<article id=\"entry-dgp-10233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διό</h1><div class=\"entry-meta\"><span>DGP · ordem 1715 na letra δ · nº geral 10233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. (causa) 1 eis porque; por isso 2 porque. 〈διά, ὅ〉</p></section></article>\n<article id=\"entry-dgp-10234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιόβλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1716 na letra δ · nº geral 10234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atingido por Zeus; fulminado 2 lançado; enviado por Zeus. 〈∆ιός, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-10235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιόβολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1717 na letra δ · nº geral 10235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançado por Zeus. 〈∆ιός, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-10236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διογενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1718 na letra δ · nº geral 10236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nascido de Zeus; descendente de Zeus 2 divino. 〈∆ιός, γένος〉</p></section></article>\n<article id=\"entry-dgp-10237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιογένης, ους (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1719 na letra δ · nº geral 10237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Diógenes, n. de h.</p></section></article>\n<article id=\"entry-dgp-10238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόγκωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1720 na letra δ · nº geral 10238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inchação; dilatação. 〈διά, ὀγκόω〉</p></section></article>\n<article id=\"entry-dgp-10239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόγονος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1721 na letra δ · nº geral 10239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διογενής.</p></section></article>\n<article id=\"entry-dgp-10240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοδεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1722 na letra δ · nº geral 10240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διώδευον) atravessar; percorrer, ac. ou gen.</p></section></article>\n<article id=\"entry-dgp-10241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοδοιπορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1723 na letra δ · nº geral 10241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(m.-q.-perf. 3ª pl. διωδοιπορήκεσαν) atravessar; percorrer.</p></section></article>\n<article id=\"entry-dgp-10242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίοδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1724 na letra δ · nº geral 10242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passagem estreita; caminho; rua 2 encruzilhada 3 autorização de passagem; salvo-conduto 4 Medic. evacuação. 〈διά, ὁδός〉</p></section></article>\n<article id=\"entry-dgp-10243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1725 na letra δ · nº geral 10243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ou ἐκ ∆ιόθεν proveniente de Zeus; por ordem de Zeus. 〈∆ιός〉</p></section></article>\n<article id=\"entry-dgp-10244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1726 na letra δ · nº geral 10244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διοίγω abrir. 〈διά, οἴγνυμι, οἴγω〉</p></section></article>\n<article id=\"entry-dgp-10245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοιδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1727 na letra δ · nº geral 10245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inchar-se. 〈διά, οιδέω〉</p></section></article>\n<article id=\"entry-dgp-10246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1728 na letra δ · nº geral 10246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διῴκουν, fut. διοικήσω, aor. διῴκησα, perf. διῴκηκα; pas. fut. διοικηθήσομαι, aor. διῳκήθην, perf. διῴκημαι e διδιῴκημαι) 1 administrar; dirigir; governar 2 alimentar 3 digerir 4 habitar (a própria casa) ♦ méd. 5 acertar para si; concluir um acordo 6 dispor 7 habitar (a própria casa). 〈διά, οἰκέω〉</p></section></article>\n<article id=\"entry-dgp-10247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίκησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1729 na letra δ · nº geral 10247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 administração; direção; governo 2 administração das despesas 3 território administrado; província. 〈διοικέω〉</p></section></article>\n<article id=\"entry-dgp-10248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοικητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1730 na letra δ · nº geral 10248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 administrador; governador 2 tesoureiro; intendente. 〈διοικέω〉</p></section></article>\n<article id=\"entry-dgp-10249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοικητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1731 na letra δ · nº geral 10249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo à administração; administrativo. 〈διοικέω〉</p></section></article>\n<article id=\"entry-dgp-10250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοικίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1732 na letra δ · nº geral 10250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διοικιῶ, aor. διῴκισα, perf. desus.) 1 dividir em aldeias uma povoação 2 separar; dividir; dispersar 3 fazer mudar de casa ♦ méd. 4 mudar de casa; estabelecer-se em um lugar, εἰς e ac. 〈διά, οἰκίζω〉</p></section></article>\n<article id=\"entry-dgp-10251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοικοδομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1733 na letra δ · nº geral 10251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διῳκοδόμησα) separar por um muro; murar; entrincheirar. 〈διά, οἰκοδομέω〉</p></section></article>\n<article id=\"entry-dgp-10252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1734 na letra δ · nº geral 10252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοϊστεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1735 na letra δ · nº geral 10253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só fut. e aor.) lançar um dardo através; furar com um dardo, gen. ou ac. 〈διά, ὀϊστεύω〉</p></section></article>\n<article id=\"entry-dgp-10254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοΐσω</h1><div class=\"entry-meta\"><span>DGP · ordem 1736 na letra δ · nº geral 10254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de διαφέρω.</p></section></article>\n<article id=\"entry-dgp-10255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίοιτο</h1><div class=\"entry-meta\"><span>DGP · ordem 1737 na letra δ · nº geral 10255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. δίω.</p></section></article>\n<article id=\"entry-dgp-10256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίχηνται</h1><div class=\"entry-meta\"><span>DGP · ordem 1738 na letra δ · nº geral 10256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. perf. jôn. de διοίχομαι.</p></section></article>\n<article id=\"entry-dgp-10257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοιχνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1739 na letra δ · nº geral 10257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caminhar em diversos sentidos; vagar; er­rar 2 atravessar, ac. 〈διά, οἰχνέω〉</p></section></article>\n<article id=\"entry-dgp-10258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοίχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1740 na letra δ · nº geral 10258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passar o tempo 2 ser concluído. 〈διά, οἴχομαι〉</p></section></article>\n<article id=\"entry-dgp-10259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοκωκή</h1><div class=\"entry-meta\"><span>DGP · ordem 1741 na letra δ · nº geral 10259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = διακωχή.</p></section></article>\n<article id=\"entry-dgp-10260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διολέσω, διολέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1742 na letra δ · nº geral 10260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διόλλυμι.</p></section></article>\n<article id=\"entry-dgp-10261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διολισθαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1743 na letra δ · nº geral 10261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διολισθάνω (impf. διωλίσθανον, aor.2 διώλισθον) 1 escorregar; deslisar através 2 escapar de; esquivar-se de, ac. 〈διά, ὀλισθάνω〉</p></section></article>\n<article id=\"entry-dgp-10262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόλλυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1744 na letra δ · nº geral 10262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διολέσω e διολῶ, aor. διώλεσα, perf. διολώλεκα) 1 fazer perecer; destruir 2 destruir moralmente; corromper 3 destruir na alma; esquecer ♦ méd. 4 perecer. 〈διά, ὄλλυμι〉</p></section></article>\n<article id=\"entry-dgp-10263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόλου</h1><div class=\"entry-meta\"><span>DGP · ordem 1745 na letra δ · nº geral 10263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. inteiramente; completamente. 〈διά, ὅλος〉</p></section></article>\n<article id=\"entry-dgp-10264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διολῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1746 na letra δ · nº geral 10264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διόλλυμι.</p></section></article>\n<article id=\"entry-dgp-10265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1747 na letra δ · nº geral 10265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pôr em fuga; repelir; expulsar.</p></section></article>\n<article id=\"entry-dgp-10266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διομαλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1748 na letra δ · nº geral 10266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manter-se com humor constante. 〈διά, ὁμαλίζω〉</p></section></article>\n<article id=\"entry-dgp-10267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διομαλύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1749 na letra δ · nº geral 10267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aplainar.</p></section></article>\n<article id=\"entry-dgp-10268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιομήδειος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 1750 na letra δ · nº geral 10268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον de Diomedes: ∆. ἀνάγκη necessidade de Diomedes, i.e., coerção imposta pela força. 〈∆ιομήδης〉</p></section></article>\n<article id=\"entry-dgp-10269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιομήδης, εος-ους (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1751 na letra δ · nº geral 10269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Diomedes, filho de Tideu, rei de Argos; filho de Ares e rei dos Bistones. 〈∆ιός, μήδομαι〉</p></section></article>\n<article id=\"entry-dgp-10270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόμνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1752 na letra δ · nº geral 10270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. méd. διωμοσάμην) 1 pronunciar um juramento; jurar, inf. fut. ♦ méd. 2 pronunciar um juramento 3 jurar, ac. ou inf. 〈διά, ὄμνυμι〉</p></section></article>\n<article id=\"entry-dgp-10271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διομολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1753 na letra δ · nº geral 10271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comprometer-se com; acomodar-se a; concordar com; admitir, inf. ♦ méd. 2 pôr-se de acordo com alguém, πρός e ac.; por um dado objeto, ac., inf. ou περί e gen.; por admitir que, or. inf.; para saber se, inter. indir. ♦ pas. 3 constituir o objeto de um acordo: διωμολογημένον ἐμοί τε καὶ σοί plat. o acordo entre mim e ti, τὰ διομολογημένα pol. as convenções concluídas. 〈διά, ὁμολογέω〉</p></section></article>\n<article id=\"entry-dgp-10272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διομολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1754 na letra δ · nº geral 10272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">convenção; acordo; pacto. 〈διο­μολογέω〉</p></section></article>\n<article id=\"entry-dgp-10273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διονομάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1755 na letra δ · nº geral 10273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 designar por um nome ♦ pas. 2 ter um nome conhecido; ser célebre. 〈διά, ὀνομάζω〉</p></section></article>\n<article id=\"entry-dgp-10274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιονύσια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1756 na letra δ · nº geral 10274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ∆ιονύσιος.</p></section></article>\n<article id=\"entry-dgp-10275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιονυσιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1757 na letra δ · nº geral 10275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 celebrar as Dionísias 2 viver como nas Bacanais; viver de modo desregrado. 〈∆ιόνυσος〉</p></section></article>\n<article id=\"entry-dgp-10276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιονυσιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1758 na letra δ · nº geral 10276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">relativo às Dionísias: ∆. θέατρον tuc. teatro de Dioniso. 〈∆ιόνυσος〉</p></section></article>\n<article id=\"entry-dgp-10277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιονύσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1759 na letra δ · nº geral 10277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Dioniso ♦ ὁ ∆ιονύσιος 2 Dionísio ou Denis, n. pr. ♦ τὰ ∆ιονύσια [ἱερά] 3 Dionísias ou Dionisíacas, festa de Dioniso em Atenas: τὰ ∆. ἀστικά ou τὰ ∆. ἐν ἄστει as Dionísias urbanas, τὰ ∆. μεγάλα as grandes Dionísias; τὰ κατ᾽ ἀγροὺς ∆. as Dionísias rurais, τὰ μικρὰ ∆. as pequenas Dionísias 4 em Roma, Bacanais. 〈∆ιόνυσος〉</p></section></article>\n<article id=\"entry-dgp-10278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιονυσοκόλακες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1760 na letra δ · nº geral 10278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aduladores de Dioniso, i.e., os atores teatrais. 〈∆ιόνυσος, κόλαξ〉</p></section></article>\n<article id=\"entry-dgp-10279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιόνυσος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1761 na letra δ · nº geral 10279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Dioniso ou Baco, filho de Zeus e de Sêmele, deus do vinho, símbolo das forças criadoras da terra; ἐν ∆ιονύσου no teatro.</p></section></article>\n<article id=\"entry-dgp-10280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόπερ</h1><div class=\"entry-meta\"><span>DGP · ordem 1762 na letra δ · nº geral 10280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. (causa) 1 é justamente por isso; por esta razão 2 porque. 〈 διά, ὅπερ〉</p></section></article>\n<article id=\"entry-dgp-10281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοπετής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1763 na letra δ · nº geral 10281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caído de Zeus; caído do céu. 〈∆ιός, πίπτω〉</p></section></article>\n<article id=\"entry-dgp-10282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίοπος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1764 na letra δ · nº geral 10282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chefe; comandante. 〈διέπω〉</p></section></article>\n<article id=\"entry-dgp-10283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοπτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1765 na letra δ · nº geral 10283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 observar atentamente; espionar; examinar 2 discernir; distinguir 3 ser inspetor de navio. 〈διόψομαι〉</p></section></article>\n<article id=\"entry-dgp-10284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοπτήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1766 na letra δ · nº geral 10284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espião 2 sub-oficial. 〈διόψομαι〉</p></section></article>\n<article id=\"entry-dgp-10285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορατικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1767 na letra δ · nº geral 10285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">capaz de ver bem; clarividente; dotado do dom profético. 〈διοράω〉</p></section></article>\n<article id=\"entry-dgp-10286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1768 na letra δ · nº geral 10286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διόψομαι, aor.2 διεῖδον) 1 ver bem; ver claramente; compreender a fundo; distinguir 2 ver através. 〈διά, ὁράω〉</p></section></article>\n<article id=\"entry-dgp-10287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοργίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1769 na letra δ · nº geral 10287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">irritar-se contra alguém, dat. 〈διά, ὀργίζω〉</p></section></article>\n<article id=\"entry-dgp-10288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόργυιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1770 na letra δ · nº geral 10288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que mede duas braças. 〈δίς, ὀργυιά〉</p></section></article>\n<article id=\"entry-dgp-10289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορθόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1771 na letra δ · nº geral 10289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pôr no caminho certo 2 endireitar; corrigir 3 tornar a pôr em ordem; reconciliar uma pessoa, ac., com outra, dat. ♦ méd. intr. 4 endireitar-se; corrigir-se 5 pôr-se em bom estado de defesa 6 reconciliar-se com alguém, dat. 〈διά, ὀρθόω〉</p></section></article>\n<article id=\"entry-dgp-10290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόρθωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1772 na letra δ · nº geral 10290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de endireitar 2 emenda; melhoramento; reforma 3 instrumento ou meio de melhoramento 4 meio de melhoramento. 〈διορθόω〉</p></section></article>\n<article id=\"entry-dgp-10291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόρθωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1773 na letra δ · nº geral 10291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de endireitar; restauração 2 melhoramento; melhoria 3 reparação; acerto (de uma dívida). 〈διορθόω〉</p></section></article>\n<article id=\"entry-dgp-10292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορθωτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1774 na letra δ · nº geral 10292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corretor; reformador 2 revisor; editor. 〈διορθόω〉</p></section></article>\n<article id=\"entry-dgp-10293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1775 na letra δ · nº geral 10293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διορίσω e át. διοριῶ) 1 pôr um limite em; delimitar, ac. 2 distinguir por um limite; determinar; definir 3 levar para além de um limite; banir 4 encerrar no interior de um limite ♦ méd. 5 distinguir por um limite; definir. 〈διά, ὁρίζω〉</p></section></article>\n<article id=\"entry-dgp-10294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1776 na letra δ · nº geral 10294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distinção 2 definição. 〈διορίζω〉</p></section></article>\n<article id=\"entry-dgp-10295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διοριστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1777 na letra δ · nº geral 10295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διορίζω.</p></section></article>\n<article id=\"entry-dgp-10296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόρνυμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1778 na letra δ · nº geral 10296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar-se através de, διά e gen. 〈διά, ὄρνυμι〉</p></section></article>\n<article id=\"entry-dgp-10297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διόρυγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1779 na letra δ · nº geral 10297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de cavar 2 canal 3 brecha; cavidade; furo. 〈διορύσσω〉</p></section></article>\n<article id=\"entry-dgp-10298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διορύσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1780 na letra δ · nº geral 10298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ύττω (fut. διορύξω) 1 cavar; escavar; perfurar 2 penetrar 3 minar; arruinar; destruir.</p></section></article>\n<article id=\"entry-dgp-10299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιός</h1><div class=\"entry-meta\"><span>DGP · ordem 1781 na letra δ · nº geral 10299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de Ζεύς. 〈διά, ὀρύσσω〉</p></section></article>\n<article id=\"entry-dgp-10300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δῖος, δῖα</h1><div class=\"entry-meta\"><span>DGP · ordem 1782 na letra δ · nº geral 10300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e δία, δῖον 1 divino; de origem divina 2 de Zeus; vindo de Zeus; relativo a Zeus: δῖον βούλευμα ésql. desígnio de Zeus.</p></section></article>\n";
